-- To read finance.accounts_payable.invoices,
-- a principal needs ALL THREE:
GRANT USE CATALOG ON CATALOG finance
  TO `data-analysts`;
GRANT USE SCHEMA ON SCHEMA finance.accounts_payable
  TO `data-analysts`;
GRANT SELECT ON TABLE finance.accounts_payable.invoices
  TO `data-analysts`;

REVOKE SELECT
  ON TABLE finance.accounts_payable.invoices
  FROM `data-analysts`;
